import{_ as c,a0 as l,w as d,s as p,I as r,x as o,a1 as t,A as i,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在 VirtualBox 中使用 Docker Machine 管理主机 | LCTT x X-CMD","titleTemplate":false,"description":"在 VirtualBox 中使用 Docker Machine 管理主机 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 VirtualBox 中使用 Docker Machine 管理主机 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 VirtualBox 中使用 Docker Machine 管理主机 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150527 Howto Manage Host Using Docker Machine in a VirtualBox","title":"在 VirtualBox 中使用 Docker Machine 管理主机","tag":"201508","desc":""},"relativePath":"201508/20150527 Howto Manage Host Using Docker Machine in a VirtualBox.md","filePath":"[post].md"}'),s={name:"201508/20150527 Howto Manage Host Using Docker Machine in a VirtualBox.md"};function k(u,e,h,m,x,D){const n=l("Link");return d(),p("div",null,[e[23]||(e[23]=r("h1",{id:"在-virtualbox-中使用-docker-machine-管理主机",tabindex:"-1"},[o("在 VirtualBox 中使用 Docker Machine 管理主机 "),r("a",{class:"header-anchor",href:"#在-virtualbox-中使用-docker-machine-管理主机","aria-label":"Permalink to “在 VirtualBox 中使用 Docker Machine 管理主机”"},"​")],-1)),e[24]||(e[24]=r("p",null,"大家好，今天我们学习在 VirtualBox 中使用 Docker Machine 来创建和管理 Docker 主机。Docker Machine 是一个可以帮助我们在电脑上、在云端、在数据中心内创建 Docker 主机的应用。它为根据用户的配置和需求创建服务器并在其上安装 Docker和客户端提供了一个轻松的解决方案。这个 API 可以用于在本地主机、或数据中心的虚拟机、或云端的实例提供 Docker 服务。Docker Machine 支持 Windows、OSX 和 Linux，并且是以一个独立的二进制文件包形式安装的。仍然使用（与现有 Docker 工具）相同的接口，我们就可以充分利用已经提供 Docker 基础框架的生态系统。只要一个命令，用户就能快速部署 Docker 容器。",-1)),e[25]||(e[25]=r("p",null,"本文列出一些简单的步骤用 Docker Machine 来部署 docker 容器。",-1)),e[26]||(e[26]=r("h3",{id:"_1-安装-docker-machine",tabindex:"-1"},[o("1. 安装 Docker Machine "),r("a",{class:"header-anchor",href:"#_1-安装-docker-machine","aria-label":"Permalink to “1. 安装 Docker Machine”"},"​")],-1)),r("p",null,[e[1]||(e[1]=o("Docker Machine 完美支持所有 Linux 操作系统。首先我们需要从 ",-1)),t(n,{href:"https://github.com/docker/machine/releases"},{default:i(()=>[...e[0]||(e[0]=[o("github",-1)])]),_:1}),e[2]||(e[2]=o(" 下载最新版本的 Docker Machine，本文使用 curl 作为下载工具，Docker Machine 版本为 0.2.0。",-1))]),e[27]||(e[27]=a(`<p><strong>64 位操作系统</strong></p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-amd64 &gt; /usr/local/bin/docker-machine
</code></pre><p><strong>32 位操作系统</strong></p><pre><code># curl -L https://github.com/docker/machine/releases/download/v0.2.0/docker-machine_linux-i386 &gt; /usr/local/bin/docker-machine
</code></pre><p>下载完成后，找到 <strong>/usr/local/bin</strong> 目录下的 <strong>docker-machine</strong> 文件，让其可以执行：</p><pre><code># chmod +x /usr/local/bin/docker-machine
</code></pre><p>确认是否成功安装了 docker-machine，可以运行下面的命令，它会打印 Docker Machine 的版本信息：</p><pre><code># docker-machine -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/installing-docker-machine.png" alt="安装 Docker Machine"></p><p>运行下面的命令，安装 Docker 客户端，以便于在我们自己的电脑止运行 Docker 命令：</p><pre><code># curl -L https://get.docker.com/builds/linux/x86_64/docker-latest &gt; /usr/local/bin/docker
# chmod +x /usr/local/bin/docker
</code></pre><h3 id="_2-创建-virtualbox-虚拟机" tabindex="-1">2. 创建 VirtualBox 虚拟机 <a class="header-anchor" href="#_2-创建-virtualbox-虚拟机" aria-label="Permalink to “2. 创建 VirtualBox 虚拟机”">​</a></h3>`,12)),r("p",null,[e[4]||(e[4]=o("在 Linux 系统上安装完 Docker Machine 后，接下来我们可以安装 VirtualBox 虚拟机，运行下面的就可以了。",-1)),e[5]||(e[5]=r("code",null,"--driver virtualbox",-1)),e[6]||(e[6]=o(" 选项表示我们要在 VirtualBox 的虚拟机里面部署 docker，最后的参数“linux” 是虚拟机的名称。这个命令会下载 ",-1)),t(n,{href:"https://github.com/boot2docker/boot2docker"},{default:i(()=>[...e[3]||(e[3]=[o("boot2docker",-1)])]),_:1}),e[7]||(e[7]=o(" iso，它是个基于 Tiny Core Linux 的轻量级发行版，自带 Docker 程序，然后 ",-1)),e[8]||(e[8]=r("code",null,"docker-machine",-1)),e[9]||(e[9]=o(" 命令会创建一个 VirtualBox 虚拟机（LCTT译注：当然，我们也可以选择其他的虚拟机软件）来运行这个 boot2docker 系统。",-1))]),e[28]||(e[28]=a(`<pre><code># docker-machine create --driver virtualbox linux
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/creating-docker-machine.png" alt="创建 Docker Machine"></p><p>测试下有没有成功运行 VirtualBox 和 Docker，运行命令：</p><pre><code># docker-machine ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-machine-list.png" alt="Docker Machine List"></p><p>如果执行成功，我们可以看到在 ACTIVE 那列下面会出现一个星号“*”。</p><h3 id="_3-设置环境变量" tabindex="-1">3. 设置环境变量 <a class="header-anchor" href="#_3-设置环境变量" aria-label="Permalink to “3. 设置环境变量”">​</a></h3><p>现在我们需要让 docker 与 docker-machine 通信，运行 <code>docker-machine env &lt;虚拟机名称&gt;</code> 来实现这个目的。</p><pre><code># eval &quot;$(docker-machine env linux)&quot;
# docker ps
</code></pre><p>这个命令会设置 TLS 认证的环境变量，每次重启机器或者重新打开一个会话都需要执行一下这个命令，我们可以看到它的输出内容：</p><pre><code># docker-machine env linux

export DOCKER_TLS_VERIFY=1
export DOCKER_CERT_PATH=/Users/&lt;your username&gt;/.docker/machine/machines/dev
export DOCKER_HOST=tcp://192.168.99.100:2376
</code></pre><h3 id="_4-运行-docker-容器" tabindex="-1">4. 运行 Docker 容器 <a class="header-anchor" href="#_4-运行-docker-容器" aria-label="Permalink to “4. 运行 Docker 容器”">​</a></h3><p>完成配置后我们就可以在 VirtualBox 上运行 docker 容器了。测试一下，我们可以运行虚拟机 <code>docker run busybox</code> ，并在里面里执行 <code>echo hello world</code> 命令，我们可以看到容器的输出信息。</p><pre><code># docker run busybox echo hello world
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/running-docker-container.png" alt="运行 Docker 容器"></p><h3 id="_5-拿到-docker-主机的-ip" tabindex="-1">5. 拿到 Docker 主机的 IP <a class="header-anchor" href="#_5-拿到-docker-主机的-ip" aria-label="Permalink to “5. 拿到 Docker 主机的 IP”">​</a></h3><p>我们可以执行下面的命令获取运行 Docker 的主机的 IP 地址。我们可以看到在 Docker 主机的 IP 地址上的任何暴露出来的端口。</p><pre><code># docker-machine ip
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/docker-ip-address.png" alt="Docker IP 地址"></p><h3 id="_6-管理主机" tabindex="-1">6. 管理主机 <a class="header-anchor" href="#_6-管理主机" aria-label="Permalink to “6. 管理主机”">​</a></h3><p>现在我们可以随心所欲地使用上述的 docker-machine 命令来不断创建主机了。</p><p>当你使用完 docker 时，可以运行 <strong>docker-machine stop</strong> 来停止所有主机，如果想开启所有主机，运行 <strong>docker-machine start</strong>。</p><pre><code># docker-machine stop
# docker-machine start
</code></pre><p>你也可以只停止或开启一台主机：</p><pre><code>$ docker-machine stop linux
$ docker-machine start linux
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>最后，我们使用 Docker Machine 成功在 VirtualBox 上创建并管理一台 Docker 主机。Docker Machine 确实能让用户快速地在不同的平台上部署 Docker 主机，就像我们这里部署在 VirtualBox 上一样。这个 virtualbox 驱动可以在本地机器上使用，也可以在数据中心的虚拟机上使用。Docker Machine 驱动除了支持本地的 VirtualBox 之外，还支持远端的 Digital Ocean、AWS、Azure、VMware 以及其它基础设施。</p><p>如果你有任何疑问，或者建议，请在评论栏中写出来，我们会不断改进我们的内容。谢谢，祝愉快。</p><hr>`,29)),r("p",null,[e[11]||(e[11]=o("via: ",-1)),t(n,{href:"http://linoxide.com/linux-how-to/host-virtualbox-docker-machine/"},{default:i(()=>[...e[10]||(e[10]=[o("http://linoxide.com/linux-how-to/host-virtualbox-docker-machine/",-1)])]),_:1})]),r("p",null,[e[15]||(e[15]=o("作者：",-1)),t(n,{href:"http://linoxide.com/author/arunp/"},{default:i(()=>[...e[12]||(e[12]=[o("Arun Pyasi",-1)])]),_:1}),e[16]||(e[16]=o(" 译者：",-1)),t(n,{href:"https://github.com/bazz2"},{default:i(()=>[...e[13]||(e[13]=[o("bazz2",-1)])]),_:1}),e[17]||(e[17]=o(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...e[14]||(e[14]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[20]||(e[20]=o("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[18]||(e[18]=[o("LCTT",-1)])]),_:1}),e[21]||(e[21]=o(" 原创翻译，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...e[19]||(e[19]=[o("Linux中国",-1)])]),_:1}),e[22]||(e[22]=o(" 荣誉推出",-1))])])}const M=c(s,[["render",k]]);export{T as __pageData,M as default};
